ROOT = Path(__file__).resolve().parents[1]
DIAGRAMS = ROOT / 'diagrams'
esc = html.escape


def diagram(name, title, subtitle, nodes, edges, width=1200, height=740):
    parts = [f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {height}" role="img" aria-label="{esc(title)}"><title>{esc(title)}</title><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10" fill="#aa9871"/></marker></defs><style>text{{font-family:Segoe UI,Arial,sans-serif}}.name{{font-size:21px;fill:#f0dfba;font-weight:600}}.detail{{font-size:15px;fill:#b5c8c6}}.tag{{font-size:11px;letter-spacing:1.6px;fill:#93b6a3}}.edge{{font-size:12px;fill:#c5b686}}</style><rect width="100%" height="100%" rx="18" fill="#101f26"/><text x="36" y="44" font-family="Georgia" font-size="29" fill="#f0dfba">{esc(title)}</text><text x="36" y="73" class="detail">{esc(subtitle)}</text>''']
    for path, label, x, y in edges:
        parts.append(f'<path d="{path}" stroke="#aa9871" stroke-width="2" fill="none" marker-end="url(#arrow)"/>')
        if label:
            parts.append(f'<text x="{x}" y="{y}" text-anchor="middle" class="edge">{esc(label)}</text>')
    for x, y, w, tag, label, lines in nodes:
        parts.append(f'<rect x="{x}" y="{y}" width="{w}" height="122" rx="10" fill="#20363c" stroke="#758576" stroke-opacity=".7"/><rect x="{x}" y="{y}" width="4" height="122" rx="2" fill="#b7a16a"/><text x="{x+18}" y="{y+24}" class="tag">{esc(tag)}</text><text x="{x+18}" y="{y+52}" class="name">{esc(label)}</text>')
        for i, line in enumerate(lines):
            parts.append(f'<text x="{x+18}" y="{y+80+i*21}" class="detail">{esc(line)}</text>')
    parts.append('</svg>')
    (DIAGRAMS / f'{name}.svg').write_text(''.join(parts), encoding='utf-8')


