source=(ROOT/'arena-loop-proposal.md').read_text(encoding='utf-8')
chart_names=['arena-overall','arena-sections','arena-items','arena-ladder','arena-employees']
for name,body in zip(chart_names,re.findall(r'```mermaid\n(.*?)```',source,re.S)):
    (DIAGRAMS/(name+'.mmd')).write_text(body.strip()+'\n',encoding='utf-8')


def inline(text):
    text=esc(text)
    text=re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',text)
    return re.sub(r'`([^`]+)`',r'<code>\1</code>',text)


def render_proposal(text):
    lines=text.splitlines();out=[];i=0;chart=0
    while i<len(lines):
        line=lines[i]
        if not line.strip():i+=1;continue
        if line.startswith('```mermaid'):
            i+=1
            while i<len(lines) and not lines[i].startswith('```'):i+=1
            name=chart_names[chart];chart+=1;i+=1
            out.append(f'<figure><img src="diagrams/{name}.svg" alt="{name.replace("arena-", "").replace("-", " ")} progression flowchart"><figcaption>Visual summary · <a href="diagrams/{name}.svg">Open full size</a> · <a href="diagrams/{name}.mmd">Mermaid source</a></figcaption></figure>');continue
        h=re.match(r'^(#{1,3}) (.*)',line)
        if h:
            level=min(4,len(h[1])+1);out.append(f'<h{level}>{inline(h[2])}</h{level}>');i+=1;continue
        if line.startswith('|'):
            rows=[]
            while i<len(lines) and lines[i].startswith('|'):
                cells=[x.strip() for x in lines[i].strip('|').split('|')]
                if not all(re.fullmatch(r':?-+:?',x) for x in cells):rows.append(cells)
                i+=1
            out.append('<div class="table-scroll"><table><thead><tr>'+''.join('<th>'+inline(c)+'</th>' for c in rows[0])+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+inline(c)+'</td>' for c in row)+'</tr>' for row in rows[1:])+'</tbody></table></div>');continue
        if re.match(r'^(- |\d+\. )',line):
            tag='ul' if line.startswith('- ') else 'ol';items=[]
            while i<len(lines) and re.match(r'^(- |\d+\. )',lines[i]):
                items.append('<li>'+inline(re.sub(r'^(- |\d+\. )','',lines[i]))+'</li>');i+=1
            out.append('<'+tag+'>'+''.join(items)+'</'+tag+'>');continue
        paragraph=[line];i+=1
        while i<len(lines) and lines[i].strip() and not re.match(r'^(#|\||```|- |\d+\. )',lines[i]):paragraph.append(lines[i]);i+=1
        out.append('<p>'+inline(' '.join(paragraph))+'</p>')
    return ''.join(out)


